/**
 * A list beside the selected item's detail (`design/archetypes/master-detail-page.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/master-detail-page.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, onCleanup, onMount, type JSX } from 'solid-js'

import {
  afterRender,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  masterDetailFocus,
  masterDetailHolds,
  resolveSlot,
  scope,
  watchEffect,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/archetypes/master-detail-page.module.css'
import Button from '../controls/Button'
import EmptyState, { type EmptyStateProps } from '../structure/EmptyState'
import PageHeader from '../structure/PageHeader'
import SplitPane from '../layout/SplitPane'

export interface MasterDetailPageProps {
  /**
   * Vocabulary controls with at most one primary.
   */
  actions?: JSX.Element
  /**
   * The way back to the list while the detail is drawn alone.
   */
  backLabel: string
  description?: string
  /**
   * The selected item's detail. Absent means that nothing is selected.
   */
  detail?: JSX.Element
  /**
   * The detail pane while nothing is selected, in the split. Required so the page always decides
   * it.
   */
  emptyState: EmptyStateProps
  /**
   * The list pane: a List (or a Table or a Tree) with its FilterBar and its pagination. The
   * application marks the selected item `current`.
   */
  list: JSX.Element
  /**
   * Names the list pane's region and the split's separator.
   */
  listLabel: string
  /**
   * Called by the way back. The application clears its selection here.
   */
  onBack: () => void
  title: string
}

/** A list beside the selected item's detail. */
export default function MasterDetailPage(given: MasterDetailPageProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const narrow = createCell(false)
    const held = createCell(false)
    const selected = createCell(false)
    const body = elementRef<HTMLElement>()
    const root = elementRef<HTMLElement>()
    const actionsSlot = resolveSlot(() => props.actions)
    const detailSlot = resolveSlot(() => props.detail)
    const measure = createDerived(() => () => {
      if (root.value === null) return
      const rem = Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
      narrow.value = root.value.getBoundingClientRect().width < 48 * rem
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const run = () => {
        measure.value()
      }
      const resize = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(run)
      for (const element of [root.value]) if (element) resize?.observe(element)
      release1 = () => {
        resize?.disconnect()
      }
      run()
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    const effect2 = () => {
      selected.value = Boolean(detailSlot.filled())
    }
    watchEffect(
      createMemo(() => Boolean(detailSlot.filled())),
      effect2,
      true,
    )
    let release3: (() => void) | undefined
    const effect3 = () => {
      release3?.()
      const listener = ($event: FocusEvent) => {
        held.value = masterDetailHolds(body.value, $event)
      }
      document.addEventListener('focusin', listener)
      release3 = () => document.removeEventListener('focusin', listener)
    }
    onMount(effect3)
    onCleanup(() => release3?.())
    const effect4 = () => {
      afterRender(() => masterDetailFocus(body.value, held.value))
    }
    watchEffect(
      createMemo(() =>
        narrow.value
          ? selected.value
            ? 'detail'
            : 'list'
          : selected.value
            ? 'split-detail'
            : 'split',
      ),
      effect4,
      false,
    )
    return (
      <div
        class={styles.page}
        data-layout={narrow.value ? 'single' : 'split'}
        data-pane={narrow.value ? (selected.value ? 'detail' : 'list') : undefined}
        data-member="master-detail-page"
        ref={root.attach}
      >
        <PageHeader
          title={props.title}
          description={props.description}
          actions={actionsSlot.filled() ? actionsSlot() : undefined}
        />
        {/* body */}
        <div class={styles.body} ref={body.attach}>
          {narrow.value ? (
            <>
              {/* list */}
              <section
                class={styles.list}
                aria-label={props.listLabel}
                tabindex="-1"
                hidden={selected.value}
                data-master-detail-page-part="list"
              >
                {props.list}
              </section>
              {selected.value ? (
                <div class={styles.detail} data-master-detail-page-part="detail">
                  {/* back */}
                  <div class={styles.back} data-master-detail-page-part="back">
                    <Button
                      variant="ghost"
                      tone="neutral"
                      size="sm"
                      icon="back"
                      label={props.backLabel}
                      onClick={() => props.onBack?.()}
                    />
                  </div>
                  {/* scroll */}
                  <div class={styles.scroll}>{detailSlot()}</div>
                </div>
              ) : null}
            </>
          ) : (
            <SplitPane
              label={props.listLabel}
              defaultRatio={0.32}
              startMin={240}
              endMin={420}
              start={
                <section
                  class={styles.list}
                  aria-label={props.listLabel}
                  tabindex="-1"
                  data-master-detail-page-part="list"
                >
                  {props.list}
                </section>
              }
              end={
                <div class={styles.detail} data-master-detail-page-part="detail">
                  {selected.value ? (
                    <div class={styles.scroll}>{detailSlot()}</div>
                  ) : (
                    <div class={styles.empty}>
                      <EmptyState
                        icon={props.emptyState.icon}
                        title={props.emptyState.title}
                        description={props.emptyState.description}
                        action={
                          props.emptyState.action !== undefined
                            ? props.emptyState.action
                            : undefined
                        }
                        secondaryAction={
                          props.emptyState.secondaryAction !== undefined
                            ? props.emptyState.secondaryAction
                            : undefined
                        }
                      />
                    </div>
                  )}
                </div>
              }
            />
          )}
        </div>
      </div>
    )
  })
}
